"""Deterministic catalog seed source adapter for Discovery local development.

Provides 60 distinct, realistic, offline-first fashion product records covering:
- Tops (14)
- Bottoms (12)
- Outerwear (12)
- Footwear (12)
- Accessories (10)

Spanning a balanced mix of Indian contemporary/heritage craftsmanship and global
smart-casual/minimalist/streetwear aesthetics, priced in INR (₹999 to ₹14,999).

Every record conforms to the SourceAdapter protocol and is explicitly marked as a
synthetic development fixture (`attributes.fixture = True`, `attributes.synthetic = True`,
and explicit fixture note). Identifiers and payloads are 100% deterministic with
mathematically valid GS1 test GTIN-14 check digits.
"""

from __future__ import annotations

from typing import Optional

from app.domain.ports.source_adapter import RawSourceRecord, SourceBatch

FASHION_SEED_SOURCE_ID = "fashion_seed"
_FIXTURE_NOTE = "FIXTURE — synthetic test seed record, not real commerce data"


def compute_test_gtin14(sequence_id: int) -> str:
    """Generate a deterministic, mathematically valid GTIN-14 test identifier.

    Uses a test GS1-style sequence with calculated modulo-10 check digit so it
    passes pure-python GTIN check-digit verification without masquerading as a
    real retail barcode.
    """
    base_13 = f"8901000{sequence_id:06d}"
    digits = [int(ch) for ch in base_13]
    total = sum(d * (3 if i % 2 == 0 else 1) for i, d in enumerate(reversed(digits)))
    check_digit = (10 - (total % 10)) % 10
    return (base_13 + str(check_digit)).zfill(14)


def _seed_payload(
    *,
    record_id: str,
    sequence_id: int,
    title: str,
    brand: str,
    category: str,
    subcategory: str,
    price: float,
    color: str,
    material: str,
    fit: str,
    silhouette: str,
    style_tags: tuple[str, ...],
    season: str = "all-season",
) -> dict:
    gtin = compute_test_gtin14(sequence_id)
    return {
        "id": record_id,
        "title": title,
        "brand": brand,
        "category": category,
        "subcategory": subcategory,
        "price": price,
        "currency": "INR",
        "availability": True,
        "product_url": f"https://catalog.fixture.test/products/{record_id}",
        "image_urls": [f"https://cdn.fixture.test/fashion/{record_id}.jpg"],
        "gtin": gtin,
        "attributes": {
            "fixture": True,
            "synthetic": True,
            "note": _FIXTURE_NOTE,
            "color": color,
            "material": material,
            "fit": fit,
            "silhouette": silhouette,
            "style_tags": list(style_tags),
            "season": season,
        },
    }


def _build_raw_record(
    record_id: str,
    sequence_id: int,
    title: str,
    brand: str,
    category: str,
    subcategory: str,
    price: float,
    color: str,
    material: str,
    fit: str,
    silhouette: str,
    style_tags: tuple[str, ...],
    season: str = "all-season",
) -> RawSourceRecord:
    return RawSourceRecord(
        source=FASHION_SEED_SOURCE_ID,
        source_record_id=record_id,
        payload=_seed_payload(
            record_id=record_id,
            sequence_id=sequence_id,
            title=title,
            brand=brand,
            category=category,
            subcategory=subcategory,
            price=price,
            color=color,
            material=material,
            fit=fit,
            silhouette=silhouette,
            style_tags=style_tags,
            season=season,
        ),
    )


