class FashionCatalogSeedAdapter:
    """Deterministic fashion catalog seeder conforming to ``SourceAdapter``."""

    source_id = FASHION_SEED_SOURCE_ID

    def __init__(
        self,
        records: tuple[RawSourceRecord, ...] = FASHION_SEED_RECORDS,
        *,
        page_size: int = 50,
    ) -> None:
        self._records = tuple(records)
        self._page_size = max(1, page_size)

    def fetch_batch(
        self,
        *,
        continuation: Optional[str] = None,
        limit: int = 50,
    ) -> SourceBatch:
        start = int(continuation) if continuation is not None else 0
        size = min(limit, self._page_size)
        chunk = self._records[start : start + size]
        next_start = start + size
        nxt = str(next_start) if next_start < len(self._records) else None
        return SourceBatch(source=self.source_id, records=chunk, continuation=nxt)
